# What about counting "reachable" positions through non-6 paths?

def reach_count(grid, i, j):
    """BFS from (i,j) counting how many non-6 cells are reachable"""
    visited = set()
    queue = [(i,j)]
    visited.add((i,j))
    while queue:
        cur_i, cur_j = queue.pop(0)
        for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]:
            ni,nj = cur_i+di, cur_j+dj
            if 0 <= ni < h and 0 <= nj < w and (ni,nj) not in visited:
                if grid[ni][nj] != 6:
                    visited.add((ni,nj))
                    queue.append((ni,nj))
    return len(visited)

